card:
{{define "app-card-atom-begin-card"}}<article class="app-tile" data-app-tile="{{.Slug}}">{{end}}
{{define "app-card-atom-begin-summary"}}<a class="app-summary" href="{{.URL}}" data-app-open="{{.Slug}}">{{end}}
{{define "app-card-atom-icon"}}{{.Icon}}{{end}}
{{define "app-card-atom-begin-copy"}}<span class="app-copy">{{end}}
{{define "app-card-atom-name"}}<strong>{{.Name}}</strong>{{end}}
{{define "app-card-atom-description"}}<span>{{.Description}}</span>{{end}}
{{define "app-card-atom-end-copy"}}</span>{{end}}
{{define "app-card-atom-end-summary"}}</a>{{end}}
{{define "app-card-atom-manage"}}<a class="control-icon-button" href="{{.URL}}" data-app-open="{{.Slug}}" data-app-manage {{if .ManageHidden}}hidden{{end}} aria-label="{{.ManageLabel}}: {{.Name}}" title="{{.ManageLabel}}">{{.More}}</a>{{end}}
{{define "app-card-atom-connect"}}{{if .Unavailable}}<a class="control-icon-button" href="{{.URL}}" data-app-open="{{.Slug}}" data-app-add {{if .AddHidden}}hidden{{end}} aria-label="{{.AboutLabel}}: {{.Name}}">{{.Plus}}</a>{{else}}<form method="post" action="/apps/configure" data-app-action data-app-toolkit="{{.Slug}}" data-app-quick {{if .AddHidden}}hidden{{end}}>{{.InterfaceReference}}<input type="hidden" name="action" value="connect"><input type="hidden" name="toolkit" value="{{.Slug}}"><button class="control-icon-button" type="submit" aria-label="{{.ConnectLabel}} {{.Name}}" title="{{.ConnectLabel}}">{{.Plus}}</button></form>{{end}}{{end}}
{{define "app-card-atom-end-card"}}</article>{{end}}

graphics:
{{define "app-icon"}}<span class="app-logo" aria-hidden="true"><span>{{.Initial}}</span>{{if .HasIcon}}<img src="{{.IconURL}}" alt="" width="36" height="36" loading="lazy" decoding="async">{{end}}</span>{{end}}
{{define "app-plus"}}<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M12 4v16M4 12h16"/></svg>{{end}}
{{define "app-more"}}<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>{{end}}

account:
{{define "app-account-view-copy"}}<div class="setting-copy"><strong>{{.Name}} · {{.Alias}}</strong><p data-connection-status="{{.Status}}">{{.StatusLabel}}</p>{{.Warning}}
{{.Authorization}}</div>
{{end}}
{{define "app-account-view-actions"}}<form method="post" action="/apps/configure" data-app-action class="app-account-actions" data-settings-confirm="{{.Confirm}}" data-confirm-description="{{.Description}}">{{.Identity}}{{.Buttons}}</form>{{end}}
{{define "app-account-view-button"}}<button class="secondary" name="action" value="{{.Action}}">{{.Label}}</button>{{end}}

connect.program:
{{define "app-connect-view-unavailable"}}<span class="app-unavailable-action"><button type="button" disabled>{{.ConnectLabel}}</button>{{.Help}}</span>
{{end}}
{{define "app-connect-view-first"}}<form method="post" action="/apps/configure" data-app-action data-app-toolkit="{{.Slug}}" data-app-first {{if .FirstHidden}}hidden{{end}}>{{.Identity}}<button type="submit">{{.FirstLabel}}</button></form>
{{end}}
{{define "app-connect-view-additional"}}<details class="app-add-account" data-app-add-account {{if .AdditionalHidden}}hidden{{end}}><summary>{{.AddAccountLabel}}</summary><form method="post" action="/apps/configure" data-app-action data-app-toolkit="{{.Slug}}" data-app-additional>{{.Identity}}<label>{{.AccountLabel}}<input name="alias" placeholder="work" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" maxlength="64" required></label><button type="submit">{{.ConnectAccountLabel}}</button></form></details>{{end}}
